  const s0 = () => { stepsBar(0); $('#sc', main).innerHTML = `<div class="grid g3">${DTYPES.map(d => `<div class="card cl" data-t="${d.k}" style="cursor:pointer;${st.type === d.k ? 'border-color:#235B4E;background:rgba(35,91,78,.08)' : ''}"><b>${d.name}</b><p class="tiny dim" style="margin:6px 0">${d.desc}</p><div class="mono tiny">${d.ext}</div></div>`).join('')}</div><div style="margin-top:14px;text-align:right"><button class="btn pri" id="nx">Continuar →</button></div>`; };
