  const s2 = () => { stepsBar(2); const dt = DTYPES.find(d => d.k === st.type); $('#sc', main).innerHTML = `<div class="card"><h3>Archivos — ${dt.name}</h3><div class="drop" id="dz" style="margin-top:10px">Suelte aquí sus archivos (${dt.ext}) o haga clic<br><span class="tiny">Campos requeridos: ${dt.req.join(', ') || 'ninguno'} · la validación es local en su navegador</span><input type="file" id="fi" multiple hidden></div><div id="fl" class="tiny" style="margin-top:8px">${st.files.map(f => `<div class="mono">${esc(f.name)} <span class="dim">${fmt(f.size / 1024)} KB</span></div>`).join('')}</div></div><div style="margin-top:14px;display:flex;justify-content:space-between"><button class="btn ghost" id="bk">← Atrás</button><button class="btn pri" id="nx" ${st.files.length ? '' : 'disabled'}>Validar →</button></div>`; const dz = $('#dz', main), fi = $('#fi', main); dz.onclick = () => fi.click(); const add = fl => { st.files.push(...fl); s2(); }; fi.onchange = () => add([...fi.files]); ['dragover', 'dragenter'].forEach(ev => dz.addEventListener(ev, e => { e.preventDefault(); dz.classList.add('over'); })); ['dragleave', 'drop'].forEach(ev => dz.addEventListener(ev, e => { e.preventDefault(); dz.classList.remove('over'); })); dz.addEventListener('drop', e => add([...e.dataTransfer.files])); };
